CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'admin',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used_at TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS site_settings (id INTEGER PRIMARY KEY,content TEXT NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_settings_draft (id INTEGER PRIMARY KEY,content TEXT NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_versions (id TEXT PRIMARY KEY,content TEXT NOT NULL,note TEXT,created_by TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS treatment_categories (id TEXT PRIMARY KEY,name TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS treatments (id TEXT PRIMARY KEY,category_id TEXT NULL,name TEXT NOT NULL,description TEXT NOT NULL,price REAL NOT NULL DEFAULT 0,price_from INTEGER NOT NULL DEFAULT 0,image_url TEXT NULL,featured INTEGER NOT NULL DEFAULT 0,visible INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,bio TEXT NOT NULL,phone TEXT NOT NULL,image_url TEXT NULL,facebook_url TEXT NULL,instagram_url TEXT NULL,visible INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS gallery_images (id TEXT PRIMARY KEY,url TEXT NOT NULL,alt TEXT NOT NULL,caption TEXT NOT NULL,visible INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS opening_hours (weekday INTEGER PRIMARY KEY,opens TEXT NULL,closes TEXT NULL,closed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS special_opening_hours (id TEXT PRIMARY KEY,date TEXT NOT NULL,label TEXT NOT NULL,opens TEXT NULL,closes TEXT NULL,closed INTEGER NOT NULL DEFAULT 0);
